query {
  drug(chemblId: "CHEMBL939") {
    id
    name
    drugType
    maximumClinicalTrialPhase
    isApproved
    synonyms
    tradeNames
    description
    mechanismsOfAction {
      rows {
        mechanismOfAction
        actionType
        targetName
        targets { id approvedSymbol }
        references { source }
      }
    }
  }
}

